'use strict';
// In-memory reply versions. Keep the original text, including invalid or wrapped JSON.
function rememberAIReply(entries,text,{notation='auto',selected=0,label='Trước khi thay nội dung'}={}){
  if(typeof text!=='string'||!text.trim())return {entries,id:''};
  const previous=entries.find(v=>v.text===text&&v.notation===notation);if(previous)return {entries,id:previous.id};
  let title='Phản hồi chưa phân tích được';try{const cases=parseCases(text,notation);title=cases[Math.min(selected,cases.length-1)]?.title||title}catch{}
  const version={id:crypto.randomUUID(),createdAt:Date.now(),label,title,text,notation,selected};
  return {entries:[...entries,version].slice(-8),id:version.id};
}
// Compare validated data by elapsed minute. Never infer that two exams at different times are the same exam.
function compareAICases(before,after){
  const rows=[],same=(a,b)=>JSON.stringify(blank(a)?null:a)===JSON.stringify(blank(b)?null:b);
  const show=(value,key)=>blank(value)?'Chưa ghi':key==='fluid'?fluidDisplay(value,'vn'):key==='station'&&value>0?'+'+value:typeof value==='object'?JSON.stringify(value):String(value);
  const add=(label,a,b,{moment='',key='',kind}={})=>{if(same(a,b))return;rows.push({id:rows.length,label,moment,before:show(a,key),after:show(b,key),kind:kind||(blank(a)?'added':blank(b)?'removed':'changed')})};
  for(const [key,label] of [['title','Tên ca'],['narrative','Đề bài'],['assessment','Nhận định đã ghi'],['plan','Kế hoạch đã ghi']])add(label,before[key],after[key]);
  for(const [key,label] of [['name','Họ tên'],['code','Mã ca'],['para','Para'],['gestationalAge','Tuổi thai'],['riskFactors','Tiền căn / nguy cơ'],['onset','Khởi phát'],['rupturedAt','Thời điểm vỡ ối'],['presentation','Ngôi ban đầu'],['fetalPosition','Kiểu thế ban đầu'],['date','Ngày bắt đầu'],['dateLabel','Ngày ghi trong đề'],['startTime','Giờ bắt đầu'],['pushingStart','Bắt đầu rặn · giờ từ đầu']])add(label,before.patient[key],after.patient[key]);
  const fields=[...FIELD_DEFS,{key:'headMarker',label:'Ký hiệu đầu đã đặt'},{key:'contractionCells',label:'Các ô cơn co đã tô'}],byMinute=c=>new Map(c.observations.map(o=>[Math.round(o.time*60),o]));
  const old=byMinute(before),next=byMinute(after),describe=o=>fields.filter(f=>!blank(o[f.key])).map(f=>f.label+': '+show(o[f.key],f.key)).join('\n')||'Mốc chưa có số đo';
  for(const minute of [...new Set([...old.keys(),...next.keys()])].sort((a,b)=>a-b)){
    const a=old.get(minute),b=next.get(minute),hour=Math.floor(minute/60),rest=minute%60,elapsed=hour+' giờ'+(rest?' '+rest+' phút':''),clock=[a&&clockAt(before,a.time),b&&clockAt(after,b.time)].filter(Boolean),moment='Từ đầu '+elapsed+' · '+[...new Set(clock)].join(' → ');
    if(!a||!b){add('Mốc theo dõi',a?describe(a):'Không có mốc này',b?describe(b):'Không có mốc này',{moment,kind:a?'removed':'added'});continue}
    for(const f of fields)add(f.label,a[f.key],b[f.key],{moment,key:f.key});
  }
  const events=c=>{const map=new Map();for(const e of c.events||[]){const minute=Math.round(e.time*60);map.set(minute,[...(map.get(minute)||[]),e.label])}return map};
  const oldEvents=events(before),newEvents=events(after);
  for(const minute of [...new Set([...oldEvents.keys(),...newEvents.keys()])].sort((a,b)=>a-b))add('Sự kiện',oldEvents.get(minute)?.join('\n'),newEvents.get(minute)?.join('\n'),{moment:'Từ đầu '+Math.floor(minute/60)+' giờ'+(minute%60?' '+minute%60+' phút':'')+' · '+[...new Set([oldEvents.has(minute)&&clockAt(before,minute/60),newEvents.has(minute)&&clockAt(after,minute/60)].filter(Boolean))].join(' → ')});
  return rows;
}
