  if(!mapping.includes('time'))throw Error('Chọn một cột thời gian.');const used=mapping.filter(Boolean);if(new Set(used).size!==used.length)throw Error('Mỗi trường chỉ được gán cho một cột.');
  const [sh,sm]=startTime.split(':').map(Number),observations=[],events=[],notes=[];let previous=-1,day=0;const seen=new Set();
  for(const [i,row] of grid.rows.entries()){
    const value=row[mapping.indexOf('time')];let time;const clock=value.match(/^(\d{1,2}):([0-5]\d)(?:\s*\(?(?:\+|ngày\s*\+?)(\d+)d?\)?)?$/i);
    if(clock){const h=Number(clock[1]);if(h>23)throw Error('Dòng '+(i+2)+': giờ vượt 23.');const mins=h*60+Number(clock[2]);day=clock[3]===undefined?day:Number(clock[3]);time=(mins+day*1440-sh*60-sm)/60;if(clock[3]===undefined&&time<previous){day++;time+=24;notes.push('Dòng '+(i+2)+': hiểu '+value+' là ngày hôm sau.')}}else if(/^\d+(?:[.,]\d+)?$/.test(value)){time=Number(value.replace(',','.'))}else throw Error('Dòng '+(i+2)+': dùng HH:mm, HH:mm (+1d), hoặc số giờ từ lúc bắt đầu; xác định lại giờ tương đối.');
    if(!validElapsed(time))throw Error('Dòng '+(i+2)+': mốc phải thuộc 0–72 giờ, chính xác đến phút.');time=minuteTime(time);if(seen.has(time))throw Error('Dòng '+(i+2)+': trùng mốc '+value+'. Hãy gộp dữ kiện sau khi đối chiếu.');seen.add(time);previous=time;
    const o={time};for(let j=0;j<mapping.length;j++){const key=mapping[j],v=row[j];if(!key||key==='time'||!v)continue;if(key==='event'){events.push({time,label:v});continue}const f=FIELD_DEFS.find(f=>f.key===key);o[key]=f.type==='text'||f.options?v:Number(v.replace(',','.'))}observations.push(o);
  }
