  s.play=()=>{if(s.player){s.pause();return}s.player=true;const tick=()=>{const times=api.current().observations.map(o=>o.time),current=api.time(),next=times.find(t=>t>current);if(next===undefined){s.pause();return}if(api.navigate(next)===false){s.pause();return}timer=setTimeout(tick,s.speed)};if(api.time()>=api.current().observations.at(-1).time)api.navigate(api.current().observations[0].time);timer=setTimeout(tick,s.speed)};
  watch(()=>[api.projectKey(),s.panel,api.home()],()=>s.pause());
