  s.toggleLayer=id=>{const visible=s.layers.find(g=>g.id===id)?.visible;api.patchDesign({rowMode:'custom',sections:Object.fromEntries(CHART_SECTIONS.map(g=>[g.id,g.id===id?!visible:s.layers.find(v=>v.id===g.id)?.visible!==false]))})};
  s.isolate=id=>api.patchDesign({rowMode:'custom',sections:Object.fromEntries(CHART_SECTIONS.map(g=>[g.id,g.id===id]))});
