      key(event){if(event.key==='Escape'){event.preventDefault();event.stopPropagation();this.close(true);return}if(!['ArrowDown','ArrowUp','Home','End'].includes(event.key))return;event.preventDefault();const list=[...this.$refs.menu.querySelectorAll('button')],i=list.indexOf(document.activeElement),next=event.key==='Home'?0:event.key==='End'?list.length-1:(i+(event.key==='ArrowDown'?1:-1)+list.length)%list.length;list[next]?.focus()},
      run(action){const anchor=this.$refs.toggle;this.close();this.$emit(action);if(['favorite','archive'].includes(action))this.$nextTick(()=>{const target=anchor?.isConnected?anchor:document.getElementById('library-heading');target?.focus({preventScroll:true})})}
