      workspaceMode:state.workspaceMode,tab:['prompt','json','review'].includes(state.tab)?state.tab:'prompt',notation:['auto','who','vn'].includes(state.notation)?state.notation:'auto',selected:Number.isInteger(state.selected)?Math.max(0,state.selected):0,selectedOnly:state.selectedOnly===true,message:'',previousFocus:null,copied:false,copyBusy:false,awaiting:false,away:false,returned:false,dragging:false,active:false,provider,manualTool:null,undoText:state.undoText??null,undoNotation:state.undoNotation||'auto',previousSubject:state.previousSubject??null,suggestedSubject:state.suggestedSubject||'',repairText:state.repairText||'',includeContext:false,insertion:['replace','update'].includes(state.insertion)?state.insertion:'append',refinement:state.refinement||'',replyVersions:Array.isArray(state.replyVersions)?[...state.replyVersions]:[],historySelected:state.historySelected||'',editingReply:false,comparison:state.comparison||{source:'',index:0},
      tableOpen:false,branchMode:false,showSources:false,highlightChanges:false,editorOpen:false,timeConfirmed:false,refinementScope:'content',refinementBase:null,sentPrompt:'',sections:['title','patient','observations','events','narrative','assessment','plan','design'],partial:false,baseSnapshot:'',
      modes:[{id:'generate',title:'Sáng tạo tình huống mới',icon:'sparkles',hint:'AI tự dựng tình huống và dữ liệu giả định.'},{id:'complete',title:'Bổ sung phần thiếu',icon:'file-pen-line',hint:'Giữ dữ kiện đã có, bổ sung phần còn thiếu.'},{id:'convert',title:'Chuyển nguyên đề',icon:'file-text',hint:'Giữ dữ kiện gốc; thông số thiếu để trống.'}],
      suggestions:[{title:'Tiến triển chậm',text:'Tạo một ca chuyển dạ tiến triển chậm để luyện đọc sản đồ.'},{title:'So sánh diễn biến',text:'Các ca có diễn biến khác nhau để so sánh đường biểu diễn trên sản đồ.'},{title:'Luyện nhận xét',text:'Kèm câu hỏi yêu cầu sinh viên nhận xét diễn biến, không kèm đáp án.'},{title:'Giữ mốc đã cho',text:'Giữ nguyên các giờ và số đo tôi đã ghi; chỉ bổ sung dữ kiện còn thiếu.'}],
      tools:[{name:'ChatGPT',url:'https://chatgpt.com/',color:'#10a37f'},{name:'Gemini',url:'https://gemini.google.com/app',color:'#4f6bed'},{name:'Claude',url:'https://claude.ai/new',color:'#c96442'}]
