      format:{get(){return this.brief?.format||'free'},set(format){this.$emit('update:brief',{...this.brief,format});if(format==='multiple'&&this.promptKind!=='convert'&&this.caseCount<2)this.$emit('update:caseCount',2)}},
      featureSelection:{get(){return this.brief?.features||[]},set(features){this.$emit('update:brief',{...this.brief,features})}},
      workflowState(){return {workspaceMode:this.workspaceMode,replyVersions:this.replyVersions,historySelected:this.historySelected,comparison:this.comparison,selectedOnly:this.selectedOnly,insertion:this.insertion,undoText:this.undoText,undoNotation:this.undoNotation,previousSubject:this.previousSubject,suggestedSubject:this.suggestedSubject,repairText:this.repairText,partial:this.partial,sections:this.sections,tab:this.awaiting&&this.tab==='prompt'?'json':this.tab,reply:this.modelValue,notation:this.notation,selected:this.selected,refinement:this.refinement,refinementScope:this.refinementScope,refinementBase:this.refinementBase,tableOpen:this.tableOpen,branchMode:this.branchMode,sentPrompt:this.sentPrompt}},
      coverage(){return this.previewCase?aiCoverage(this.previewCase,this.subject,this.featureSelection):[]},
      rawCase(){return this.validation.rawCases?.[this.selected]||null},
